      q <- 0
      if (peek() == '^') {
        p <- p + 1
        k <- number()
        ch <- peek()
        if (!ch %in% c('+', '-')) {
          stop('syntax')
        }
        p <- p + 1
        q <- if (ch == '+') k else -k
      }
      if (p != nchar(text) + 1) {
        stop('syntax')
      }
      list(c = c, q = q)
